conversation_history = [
    {"role": "user", "content": "I have a Premium subscription."},
    {"role": "assistant", "content": "Got it, how can I help with your Premium subscription?"},
]

def fake_rewrite_query(raw_query, history):
    subject = None
    for turn in history:
        if "subscription" in turn["content"].lower():
            subject = "subscription"
            break

    if "it" in raw_query.lower() and subject:
        return raw_query.lower().replace("it", f"my {subject}")
    return raw_query

raw_query = "how do I cancel it"
rewritten = fake_rewrite_query(raw_query, conversation_history)

print(f"Raw query: {raw_query!r}")
print(f"Rewritten query: {rewritten!r}")
print("\nThe rewritten query gives retrieval an actual subject to search against.")
